export const getHiddenReviewIds = () => {
  try {
    return JSON.parse(localStorage.getItem(HIDDEN_REVIEWS_STORAGE_KEY) || '[]');
  } catch (e) {
    return [];
  }
};

export const getHomepageTestimonials = () => {
  const hiddenIds = new Set(getHiddenReviewIds());
  
  let userReviews = [];
  try {
    const stored = JSON.parse(localStorage.getItem('malenadu_user_reviews') || '[]');
    userReviews = stored.map(r => ({
      ...r,
      isTestimonial: true,
      isReal: true,
      hidden: Boolean(r.hidden || hiddenIds.has(r.id))
    }));
  } catch(e) {}

  const statics = HOMEPAGE_STATIC_TESTIMONIALS.map(r => ({
    ...r,
    hidden: Boolean(r.hidden || hiddenIds.has(r.id))
  }));

  // Combine user submissions first, then curated statics
  return [...userReviews, ...statics];
};

export const setReviewHiddenStatus = (reviewId, shouldHide) => {
  try {
    const hiddenIds = new Set(getHiddenReviewIds());
    if (shouldHide) {
      hiddenIds.add(reviewId);
    } else {
      hiddenIds.delete(reviewId);
    }
    const arr = Array.from(hiddenIds);
    localStorage.setItem(HIDDEN_REVIEWS_STORAGE_KEY, JSON.stringify(arr));

    // Also update in malenadu_real_reviews if it exists there
    try {
      const real = JSON.parse(localStorage.getItem('malenadu_real_reviews') || '[]');
      const updatedReal = real.map(r => r.id === reviewId ? { ...r, hidden: shouldHide } : r);
      localStorage.setItem('malenadu_real_reviews', JSON.stringify(updatedReal));
    } catch(e) {}

    // Also update in malenadu_user_reviews if it exists there
    try {
      const userRevs = JSON.parse(localStorage.getItem('malenadu_user_reviews') || '[]');
      const updatedUser = userRevs.map(r => r.id === reviewId ? { ...r, hidden: shouldHide } : r);
      localStorage.setItem('malenadu_user_reviews', JSON.stringify(updatedUser));
    } catch(e) {}

    // Dispatch global event so UI updates immediately
    window.dispatchEvent(new CustomEvent('malenadu_reviews_updated'));
    return arr;
  } catch (e) {
    return [];
  }
};

export const setBatchReviewHiddenStatus = (reviewIds, shouldHide) => {
  try {
    const hiddenIds = new Set(getHiddenReviewIds());
    reviewIds.forEach(id => {
      if (shouldHide) hiddenIds.add(id);
      else hiddenIds.delete(id);
    });
    const arr = Array.from(hiddenIds);
    localStorage.setItem(HIDDEN_REVIEWS_STORAGE_KEY, JSON.stringify(arr));

    try {
      const real = JSON.parse(localStorage.getItem('malenadu_real_reviews') || '[]');
      const targetSet = new Set(reviewIds);
      const updatedReal = real.map(r => targetSet.has(r.id) ? { ...r, hidden: shouldHide } : r);
      localStorage.setItem('malenadu_real_reviews', JSON.stringify(updatedReal));
    } catch(e) {}

    try {
      const userRevs = JSON.parse(localStorage.getItem('malenadu_user_reviews') || '[]');
      const targetSet = new Set(reviewIds);
      const updatedUser = userRevs.map(r => targetSet.has(r.id) ? { ...r, hidden: shouldHide } : r);
      localStorage.setItem('malenadu_user_reviews', JSON.stringify(updatedUser));
    } catch(e) {}

    window.dispatchEvent(new CustomEvent('malenadu_reviews_updated'));
    return arr;
  } catch (e) {
    return [];
  }
};

export const deleteUserReview = (reviewId) => {
  try {
    // 1. Remove from malenadu_user_reviews
    try {
      const userRevs = JSON.parse(localStorage.getItem('malenadu_user_reviews') || '[]');
      const updatedUser = userRevs.filter(r => r.id !== reviewId);
      localStorage.setItem('malenadu_user_reviews', JSON.stringify(updatedUser));
    } catch(e) {}

    // 2. Remove from malenadu_real_reviews
    try {
      const real = JSON.parse(localStorage.getItem('malenadu_real_reviews') || '[]');
      const updatedReal = real.filter(r => r.id !== reviewId);
      localStorage.setItem('malenadu_real_reviews', JSON.stringify(updatedReal));
    } catch(e) {}

    // 3. Ensure hidden status is set
    setReviewHiddenStatus(reviewId, true);

    window.dispatchEvent(new CustomEvent('malenadu_reviews_updated'));
  } catch(e) {}
};

export const getAllReviewsForAdmin = () => {
  const hiddenIds = new Set(getHiddenReviewIds());

  let userReviews = [];
  try {
    const stored = JSON.parse(localStorage.getItem('malenadu_user_reviews') || '[]');
    const storedReal = JSON.parse(localStorage.getItem('malenadu_real_reviews') || '[]');
    // Combine and deduplicate
    const combinedMap = new Map();
    storedReal.forEach(r => combinedMap.set(r.id, r));
    stored.forEach(r => combinedMap.set(r.id, r));

    userReviews = Array.from(combinedMap.values()).map(r => ({
      ...r,
      isReal: true,
      isTestimonial: true,
      hidden: Boolean(r.hidden || hiddenIds.has(r.id))
    }));
  } catch (e) {}

  // Master reviews with hidden flag mapped
  const master = MASTER_PRODUCT_REVIEWS.map(r => ({
    ...r,
    hidden: Boolean(r.hidden || hiddenIds.has(r.id))
  }));

  // Homepage static testimonials with hidden flag mapped
  const staticTestimonials = HOMEPAGE_STATIC_TESTIMONIALS.map(r => ({
    ...r,
    hidden: Boolean(r.hidden || hiddenIds.has(r.id))
  }));

  // Deduplicate in case a user review has the same id
  const userIds = new Set(userReviews.map(r => r.id));
  const filteredMaster = master.filter(r => !userIds.has(r.id));
  const filteredStatics = staticTestimonials.filter(r => !userIds.has(r.id));

  return [...userReviews, ...filteredStatics, ...filteredMaster];
};

export const getReviewsForProduct = (productName) => {
  if (!productName) return [];
  const pName = (productName || '').toLowerCase().trim();
  const hiddenIds = new Set(getHiddenReviewIds());
  
  // 1. Get any real reviews submitted by actual customers in localStorage
  let userReviews = [];
  try {
    const stored = JSON.parse(localStorage.getItem('malenadu_real_reviews') || '[]');
    userReviews = stored.filter(r => {
      if (r.hidden || hiddenIds.has(r.id)) return false;
      const rProd = (r.productName || r.product || '').toLowerCase().trim();
      return rProd === pName || pName.includes(rProd) || rProd.includes(pName);
    });
  } catch(e) {}

  // 2. Get master curated reviews for this product (excluding any hidden reviews)
  const matchedMaster = MASTER_PRODUCT_REVIEWS.filter(r => {
    if (r.hidden || hiddenIds.has(r.id)) return false;
    const rProd = (r.productName || r.product || '').toLowerCase().trim();
    return rProd === pName || pName.includes(rProd) || rProd.includes(pName);
  });

  // 3. User reviews appear FIRST at the very top, followed by master reviews
  const combined = [...userReviews, ...matchedMaster];
  return combined;
};
